    return `<div class="grade-view-switch"><button class="btn" data-grade-view="marks">Assignment gradebook</button><button class="btn secondary" data-grade-view="semester">Whole semester · All students</button></div>`+panel('Class gradebook',`<div class="category-summary">${Grading.ensure(currentClass).map(c=>`<span style="background:${categoryTheme(c.id).bg};color:${categoryTheme(c.id).ink};border-color:${categoryTheme(c.id).bar}">${safe(c.name)}: <b>${c.weight}%</b></span>`).join('')}</div><p class="mini-note">Students run vertically; assignments run horizontally. Each cell shows whether work has been submitted. Enter a score and move out of the field to save, and see criterion marks directly beneath the score. Select <b>Edit</b> to adjust criteria, review files or provide feedback in place.</p><div class="table-scroll grade-scroll"><table class="grade-table"><thead><tr><th class="sticky-student">STUDENT</th>${as.map(a=>`<th class="assignment-header" title="${safe(a.title)}" style="border-top:3px solid ${categoryTheme(a.categoryId).bar}">${safe(a.title)}${a.status==='Draft'?'<small>Draft</small>':''}<div class="assignment-header-badges">${categoryBadge(Grading.ensure(currentClass).find(c=>c.id===a.categoryId))}${assessmentBadge(a.assessmentType)}</div><small> / ${a.max||100} · ${safe(criteriaText(a))}</small></th>`).join('')}<th>AVERAGE</th><th>FINAL GRADE</th></tr></thead><tbody>${students.map(st=>{const gs=as.map(a=>db.grades.find(g=>g.studentId===st.id&&g.assignmentId===a.id)),present=gs.filter(Boolean),avg=present.length?(present.reduce((n,g)=>n+100*g.score/(as.find(a=>a.id===g.assignmentId)?.max||100),0)/present.length).toFixed(1)+'%':'—';return `<tr><th class="sticky-student">${safe(st.name)}</th>${as.map((a,i)=>{const sub=submissions.find(x=>x.studentId===st.id&&x.assignmentId===a.id),active=reviewTarget?.studentId===st.id&&reviewTarget?.assignmentId===a.id&&reviewTarget?.classId===currentClass;return `<td><div class="grade-cell-stack"><span class="submission-status ${sub?'submitted':'missing'}">${sub?'✓ Submitted':'○ Not submitted'}</span>${canEdit()?`<input class="grade-cell" aria-label="Grade ${safe(st.name)} ${safe(a.title)}" type="number" min="0" max="${Number(a.max||100)}" step="0.1" data-grade-student="${st.id}" data-grade-assignment="${a.id}" value="${gs[i]?.score??''}" placeholder="Grade / ${a.max||100}">`:`<span class="read-only-score">${gs[i]?.score??'Not graded'}</span>`}${inlineCriterionSummary(st.id,a,gs[i])}<button class="review-trigger ${active?'active':''}" data-review-student="${st.id}" data-review-assignment="${a.id}" aria-expanded="${active}" aria-label="${active?'Close editor for':'Edit'} ${safe(st.name)} for ${safe(a.title)}">${active?'Close':'Edit'}</button>${active?inlineGradeReview(st.id,a.id):''}</div></td>`}).join('')}<td><b>${avg}</b></td><td>${gradeFinalCell(st.id)}<small class="criterion-cell-summary">Criteria ${Criteria.summary(st.id,currentClass).overall==null?'—':Criteria.summary(st.id,currentClass).overall.toFixed(1)+'/8'}</small></td></tr>`}).join('')}</tbody></table></div>${!as.length?'<p class="empty">Create an assignment to add a gradebook column.</p>':''}`);
