  function gradeFinalCell(id){const r=Grading.result(id,currentClass);return r.complete?`<strong class="final-result">${Grading.fmt(r.final)}</strong>`:`<span class="provisional-result" title="Graded categories cover ${r.covered}% of the weighting">${r.provisional===null?'Pending':Grading.fmt(r.provisional)+' provisional'}<small>${r.covered}% category coverage</small></span>`;}
