  function openClass(id,which='stream'){if(!inClass(id)){toast('This class is not available to your account');return;}currentClass=Number(id);reviewTarget=null;tab=which;page='classroom';acknowledge(({stream:'posts',assignments:'assignments',files:'files'})[tab]||tab);if(tab==='assignments')acknowledge('feedback');render();$('#sidebar').classList.remove('open');window.scrollTo(0,0)}
