      const a=classAssignments().find(a=>a.id===Number(e.target.dataset.assignmentCategory));
      if(!a || !Grading.valid(Grading.ensure(currentClass))){alert('Category weights must total exactly 100% before assignments can be edited.');render();return;}
      if(!Grading.ensure(currentClass).some(c=>c.id===e.target.value))return;
      a.categoryId=e.target.value;save();render();toast('Assignment category updated');return;
