    if(e.target.matches('[data-grade-student]')&&page==='classroom'){if(!canEdit())return;let s=Number(e.target.dataset.gradeStudent),a=Number(e.target.dataset.gradeAssignment),ass=db.assignments.find(x=>x.id===a),val=e.target.value.trim();if(val!==''&&(!Number.isFinite(Number(val))||Number(val)<0||Number(val)>Number(ass?.max||100))){toast('Score must be between 0 and '+(ass?.max||100));render();return;}let g=db.grades.find(g=>g.studentId===s&&g.assignmentId===a);if(val===''){if(g)db.grades.splice(db.grades.indexOf(g),1)}else if(g)g.score=Number(val);else db.grades.push({studentId:s,assignmentId:a,score:Number(val)});if(db.criterionMarks)delete db.criterionMarks[`${s}:${a}`];save();const left=document.querySelector('.grade-scroll')?.scrollLeft||0;const top=window.scrollY;render();const scroller=document.querySelector('.grade-scroll');if(scroller)scroller.scrollLeft=left;window.scrollTo(0,top);toast('Grade saved');}
